### C++

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, sz;
    DSU(int n) : parent(n + 1), sz(n + 1, 1) {
        for (int i = 1; i <= n; i++) parent[i] = i;
    }
    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    bool unite(int x, int y) {
        x = find(x); y = find(y);
        if (x == y) return false;
        if (sz[x] < sz[y]) swap(x, y);
        parent[y] = x;
        sz[x] += sz[y];
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    DSU dsu(n);
    unordered_set<int> closed;
    set<pair<int, int>> edges;  // 有序存放避免重复判断复杂

    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        if (u > v) swap(u, v);
        if (edges.count({u, v})) {
            cout << "No\n";
            continue;
        }
        int ru = dsu.find(u), rv = dsu.find(v);
        if (ru != rv) {
            dsu.unite(u, v);
            cout << "No\n";
        } else {
            int root = ru;
            if (closed.find(root) == closed.end()) {
                cout << "Yes\n";
                closed.insert(root);
            } else {
                cout << "No\n";
            }
            dsu.unite(u, v);
        }
        edges.insert({u, v});
    }
    return 0;
}
